package io.github.c0rwin.coreset.testbed.faults.framework;

import java.util.Arrays;
import java.util.random.RandomGenerator;

/**
 * Content-oblivious erasure channels (Bernoulli, stationary Gilbert, deterministic block), generated by run lengths;
 * {@link #delivered} has the law of the count {@link #erase} returns.
 */
abstract class LossChannel {

    abstract String id();

    /** Stationary fraction of lost packets. */
    abstract double rate();

    /** Writes the loss pattern of {@code n} packets into {@code lost[0..n)}; returns the number delivered. */
    abstract int erase(boolean[] lost, int n, RandomGenerator rng);

    /** Number of delivered packets among {@code n}. */
    abstract int delivered(int n, RandomGenerator rng);

    /** A draw of the geometric law on {1, 2, ...} with success probability p, given {@code log1mP = ln(1 - p)}. */
    static long geometric(double log1mP, RandomGenerator rng) {
        // 1 - nextDouble() lies in (0, 1], so the logarithm is finite and <= 0; p = 1 gives log1mP = -inf and 1.
        double g = Math.floor(Math.log(1.0 - rng.nextDouble()) / log1mP);
        return g >= Long.MAX_VALUE / 2 ? Long.MAX_VALUE / 2 : 1L + (long) g;
    }

    static LossChannel bernoulli(double rho) {
        if (!(rho >= 0.0 && rho < 1.0)) {
            throw new IllegalArgumentException("loss rate must be in [0, 1): " + rho);
        }
        return new Bernoulli(rho);
    }

    /** Gilbert channel with {@code P(good -> bad) = alpha}, {@code P(bad -> good) = beta}. */
    static LossChannel gilbert(double alpha, double beta) {
        if (!(alpha > 0.0 && alpha <= 1.0 && beta > 0.0 && beta <= 1.0)) {
            throw new IllegalArgumentException("switching probabilities must be in (0, 1]: " + alpha + ", " + beta);
        }
        return new Gilbert(alpha, beta);
    }

    /** Loses the {@code round(rho n)} packets in the middle of every message, whatever the randomness. */
    static LossChannel block(double rho) {
        if (!(rho >= 0.0 && rho < 1.0)) {
            throw new IllegalArgumentException("loss rate must be in [0, 1): " + rho);
        }
        return new Block(rho);
    }

    private static final class Bernoulli extends LossChannel {
        private final double rho;
        // Runs are drawn for the rarer outcome: gaps between losses if rho <= 1/2, between deliveries otherwise.
        private final boolean sparseLoss;
        private final double log1mP;

        Bernoulli(double rho) {
            this.rho = rho;
            this.sparseLoss = rho <= 0.5;
            this.log1mP = Math.log1p(-(sparseLoss ? rho : 1.0 - rho));
        }

        @Override
        String id() {
            return "bernoulli";
        }

        @Override
        double rate() {
            return rho;
        }

        @Override
        int erase(boolean[] lost, int n, RandomGenerator rng) {
            Arrays.fill(lost, 0, n, !sparseLoss);
            if (rho == 0.0) {
                return n;
            }
            int marked = 0;
            for (long i = geometric(log1mP, rng) - 1; i < n; i += geometric(log1mP, rng)) {
                lost[(int) i] = sparseLoss;
                marked++;
            }
            return sparseLoss ? n - marked : marked;
        }

        @Override
        int delivered(int n, RandomGenerator rng) {
            if (rho == 0.0) {
                return n;
            }
            int marked = 0;
            for (long i = geometric(log1mP, rng) - 1; i < n; i += geometric(log1mP, rng)) {
                marked++;
            }
            return sparseLoss ? n - marked : marked;
        }
    }

    private static final class Gilbert extends LossChannel {
        private final double alpha;
        private final double beta;
        private final double logStayGood;
        private final double logStayBad;

        Gilbert(double alpha, double beta) {
            this.alpha = alpha;
            this.beta = beta;
            this.logStayGood = Math.log1p(-alpha);
            this.logStayBad = Math.log1p(-beta);
        }

        @Override
        String id() {
            return "gilbert";
        }

        @Override
        double rate() {
            return alpha / (alpha + beta);
        }

        @Override
        int erase(boolean[] lost, int n, RandomGenerator rng) {
            // Sojourns are geometric; by memorylessness the first one from a stationary start is too.
            boolean bad = rng.nextDouble() < rate();
            int good = 0;
            for (int i = 0; i < n; bad = !bad) {
                int end = (int) Math.min(n, i + geometric(bad ? logStayBad : logStayGood, rng));
                Arrays.fill(lost, i, end, bad);
                good += bad ? 0 : end - i;
                i = end;
            }
            return good;
        }

        @Override
        int delivered(int n, RandomGenerator rng) {
            boolean bad = rng.nextDouble() < rate();
            int good = 0;
            for (int i = 0; i < n; bad = !bad) {
                int end = (int) Math.min(n, i + geometric(bad ? logStayBad : logStayGood, rng));
                good += bad ? 0 : end - i;
                i = end;
            }
            return good;
        }
    }

    private static final class Block extends LossChannel {
        private final double rho;

        Block(double rho) {
            this.rho = rho;
        }

        private int lostCount(int n) {
            return (int) Math.round(rho * n);
        }

        @Override
        String id() {
            return "block";
        }

        @Override
        double rate() {
            return rho;
        }

        @Override
        int erase(boolean[] lost, int n, RandomGenerator rng) {
            int l = lostCount(n);
            int start = (n - l) / 2;
            Arrays.fill(lost, 0, n, false);
            Arrays.fill(lost, start, start + l, true);
            return n - l;
        }

        @Override
        int delivered(int n, RandomGenerator rng) {
            return n - lostCount(n);
        }
    }
}
